  1	using System;
  2	using System.Collections.Generic;
  3	using System.Linq;
  4	using LoadOrderKeeper.Models;
  5	using LoadOrderKeeper.Services;
  6	using LoadOrderKeeper.Tests.Fixtures;
  7	using Xunit;
  8	
  9	namespace LoadOrderKeeper.Tests;
 10	
 11	/// <summary>
 12	/// Isolation tests for <see cref="DiffService.ClassifyChanges"/>. Each test constructs
 13	/// <see cref="ModEntryModel"/> lists directly (no file I/O), computes LCS via
 14	/// <see cref="DiffService.ComputeLcs"/>, and calls <see cref="DiffService.ClassifyChanges"/>
 15	/// directly.
 16	/// </summary>
 17	/// <remarks>
 18	/// All assertions target structural properties only — <c>ChangeType</c>, <c>FileName</c>,
 19	/// <c>ReferenceNumber</c>, <c>CurrentNumber</c>, <c>DependentChanges</c> — never localized
 20	/// <c>.Text</c> content. The <see cref="EnglishLocaleFixture"/> is required because
 21	/// <c>ClassifyChanges</c> calls <c>_localization.GetString()</c> internally to populate
 22	/// <c>DiffLineModel.Text</c>, but no assertions here depend on those strings.
 23	/// </remarks>
 24	[Collection(LocaleSequentialCollection.Name)]
 25	public sealed class ClassifyChangesTests : IClassFixture<EnglishLocaleFixture>
 26	{
 27	    public ClassifyChangesTests(EnglishLocaleFixture localeFixture)
 28	    {
 29	        _ = localeFixture; // Ensures LocalizationService singleton is initialized for the lifetime of this class
 30	    }
 31	
 32	    // ------------------------------------------------------------------
 33	    // Helper: build a ModEntryModel with FileName and LineNumber set
 34	    // ------------------------------------------------------------------
 35	
 36	    private static ModEntryModel Mod(string fileName, int lineNumber)
 37	        => new ModEntryModel($"*{fileName}", lineNumber);
 38	
 39	    // ------------------------------------------------------------------
 40	    // Helper: compute LCS from two ModEntryModel lists
 41	    // ------------------------------------------------------------------
 42	
 43	    private static List<(int refIndex, int curIndex)> Lcs(
 44	        IReadOnlyList<ModEntryModel> reference,
 45	        IReadOnlyList<ModEntryModel> current)
 46	    {
 47	        var refNames = reference.Select(m => m.FileName).ToList();
 48	        var curNames = current.Select(m => m.FileName).ToList();
 49	        return DiffService.ComputeLcs(refNames, curNames, StringComparer.OrdinalIgnoreCase);
 50	    }
 51	
 52	    // ==================================================================
 53	    // Step 9a — Unchanged list returns empty result
 54	    // ==================================================================
 55	
 56	    [Fact]
 57	    public void ClassifyChanges_UnchangedList_ReturnsEmpty()
 58	    {
 59	        var reference = new[]
 60	        {
 61	            Mod("a.esm", 1),
 62	            Mod("b.esm", 2),
 63	            Mod("c.esm", 3),
 64	        };
 65	        var current = new[]
 66	        {
 67	            Mod("a.esm", 1),
 68	            Mod("b.esm", 2),
 69	            Mod("c.esm", 3),
 70	        };
 71	
 72	        var lcs    = Lcs(reference, current);
 73	        var result = DiffService.ClassifyChanges(reference, current, lcs);
 74	
 75	        Assert.Empty(result);
 76	    }
 77	
 78	    // ==================================================================
 79	    // Step 9b — Single removal with dependent Moved
 80	    // ==================================================================
 81	
 82	    [Fact]
 83	    public void ClassifyChanges_SingleRemoval_ReturnsRemovedWithDependentMoved()
 84	    {
 85	        // Reference: a(1) b(2) c(3)
 86	        // Current:   a(1) c(2)           — b removed, c shifts up
 87	        var reference = new[]
 88	        {
 89	            Mod("a.esm", 1),
 90	            Mod("b.esm", 2),
 91	            Mod("c.esm", 3),
 92	        };
 93	        var current = new[]
 94	        {
 95	            Mod("a.esm", 1),
 96	            Mod("c.esm", 2),
 97	        };
 98	
 99	        var lcs    = Lcs(reference, current);
100	        var result = DiffService.ClassifyChanges(reference, current, lcs);

101	
102	        var removed = Assert.Single(result);
103	        Assert.Equal(DiffChangeType.Removed, removed.ChangeType);
104	        Assert.Equal("b.esm", removed.FileName);
105	        Assert.Equal(2, removed.ReferenceNumber);
106	
107	        var dependent = Assert.Single(removed.DependentChanges);
108	        Assert.Equal(DiffChangeType.Moved, dependent.ChangeType);
109	        Assert.Equal("c.esm", dependent.FileName);
110	        Assert.Equal(3, dependent.ReferenceNumber);
111	        Assert.Equal(2, dependent.CurrentNumber);
112	    }
113	
114	    // ==================================================================
115	    // Step 9c — Single insertion with dependent Moved entries
116	    // ==================================================================
117	
118	    [Fact]
119	    public void ClassifyChanges_SingleInsertion_ReturnsInsertedWithDependentMoved()
120	    {
121	        // Reference: a(1) b(2) c(3)
122	        // Current:   a(1) new(2) b(3) c(4)   — new inserted, b and c shift down
123	        var reference = new[]
124	        {
125	            Mod("a.esm", 1),
126	            Mod("b.esm", 2),
127	            Mod("c.esm", 3),
128	        };
129	        var current = new[]
130	        {
131	            Mod("a.esm",   1),
132	            Mod("new.esm", 2),
133	            Mod("b.esm",   3),
134	            Mod("c.esm",   4),
135	        };
136	
137	        var lcs    = Lcs(reference, current);
138	        var result = DiffService.ClassifyChanges(reference, current, lcs);
139	
140	        var inserted = Assert.Single(result);
141	        Assert.Equal(DiffChangeType.Inserted, inserted.ChangeType);
142	        Assert.Equal("new.esm", inserted.FileName);
143	        Assert.Equal(2, inserted.CurrentNumber);
144	
145	        Assert.Equal(2, inserted.DependentChanges.Count);
146	        Assert.All(inserted.DependentChanges, dep => Assert.Equal(DiffChangeType.Moved, dep.ChangeType));
147	        Assert.Contains(inserted.DependentChanges, dep => dep.FileName == "b.esm");
148	        Assert.Contains(inserted.DependentChanges, dep => dep.FileName == "c.esm");
149	    }
150	
151	    // ==================================================================
152	    // Step 9d — Single addition at end
153	    // ==================================================================
154	
155	    [Fact]
156	    public void ClassifyChanges_AdditionAtEnd_ReturnsAddedEntry()
157	    {
158	        // Reference: a(1) b(2)
159	        // Current:   a(1) b(2) new(3)   — new appended beyond all reference mods
160	        var reference = new[]
161	        {
162	            Mod("a.esm", 1),
163	            Mod("b.esm", 2),
164	        };
165	        var current = new[]
166	        {
167	            Mod("a.esm",   1),
168	            Mod("b.esm",   2),
169	            Mod("new.esm", 3),
170	        };
171	
172	        var lcs    = Lcs(reference, current);
173	        var result = DiffService.ClassifyChanges(reference, current, lcs);
174	
175	        var added = Assert.Single(result);
176	        Assert.Equal(DiffChangeType.Added, added.ChangeType);
177	        Assert.Equal("new.esm", added.FileName);
178	        Assert.Equal(3, added.CurrentNumber);
179	        Assert.Empty(added.DependentChanges);
180	    }
181	
182	    // ==================================================================
183	    // Step 9e — Replacement at same position
184	    // ==================================================================
185	
186	    [Fact]
187	    public void ClassifyChanges_ReplacementAtSamePosition_ReturnsReplacedEntry()
188	    {
189	        // Reference: a(1) b(2)
190	        // Current:   a(1) c(2)   — b replaced by c at position 2
191	        var reference = new[]
192	        {
193	            Mod("a.esm", 1),
194	            Mod("b.esm", 2),
195	        };
196	        var current = new[]
197	        {
198	            Mod("a.esm", 1),
199	            Mod("c.esm", 2),
200	        };
201	
202	        var lcs    = Lcs(reference, current);
203	        var result = DiffService.ClassifyChanges(reference, current, lcs);
204	
205	        var replaced = Assert.Single(result);
206	        Assert.Equal(DiffChangeType.Replaced, replaced.ChangeType);
207	        Assert.Equal("b.esm", replaced.FileName);
208	        Assert.Equal("c.esm", replaced.ReplacementFileName);
209	        Assert.Empty(replaced.DependentChanges);
210	    }
211	
212	    // ==================================================================
213	    // Step 9f — Moved (swapped) mods
214	    // ==================================================================
215	
216	    [Fact]
217	    public void ClassifyChanges_SwappedMods_ReturnsTwoMovedEntries()
218	    {
219	        // Reference: a(1) b(2) c(3)
220	        // Current:   b(1) a(2) c(3)   — a and b swap positions
221	        var reference = new[]
222	        {
223	            Mod("a.esm", 1),
224	            Mod("b.esm", 2),
225	            Mod("c.esm", 3),
226	        };
227	        var current = new[]
228	        {
229	            Mod("b.esm", 1),
230	            Mod("a.esm", 2),
231	            Mod("c.esm", 3),
232	        };
233	
234	        var lcs    = Lcs(reference, current);
235	        var result = DiffService.ClassifyChanges(reference, current, lcs);
236	
237	        Assert.Equal(2, result.Count);
238	        Assert.All(result, entry => Assert.Equal(DiffChangeType.Moved, entry.ChangeType));
239	
240	        var movedA = result.Single(e => e.FileName == "a.esm");
241	        Assert.Equal(1, movedA.ReferenceNumber);
242	        Assert.Equal(2, movedA.CurrentNumber);
243	
244	        var movedB = result.Single(e => e.FileName == "b.esm");
245	        Assert.Equal(2, movedB.ReferenceNumber);
246	        Assert.Equal(1, movedB.CurrentNumber);
247	    }
248	
249	    // ==================================================================
250	    // Step 9g — Dependent change grouping under removal

250	    // Step 9g — Dependent change grouping under removal
251	    // ==================================================================
252	
253	    [Fact]
254	    public void ClassifyChanges_RemovalWithMultipleDependents_GroupsDependentsUnderRemoval()
255	    {
256	        // Reference: a(1) b(2) c(3) d(4) e(5)
257	        // Current:   a(1) c(2) d(3) e(4)   — b removed; c, d, e shift up
258	        var reference = new[]
259	        {
260	            Mod("a.esm", 1),
261	            Mod("b.esm", 2),
262	            Mod("c.esm", 3),
263	            Mod("d.esm", 4),
264	            Mod("e.esm", 5),
265	        };
266	        var current = new[]
267	        {
268	            Mod("a.esm", 1),
269	            Mod("c.esm", 2),
270	            Mod("d.esm", 3),
271	            Mod("e.esm", 4),
272	        };
273	
274	        var lcs    = Lcs(reference, current);
275	        var result = DiffService.ClassifyChanges(reference, current, lcs);
276	
277	        var removed = Assert.Single(result);
278	        Assert.Equal(DiffChangeType.Removed, removed.ChangeType);
279	        Assert.Equal("b.esm", removed.FileName);
280	
281	        Assert.Equal(3, removed.DependentChanges.Count);
282	        Assert.All(removed.DependentChanges, dep => Assert.Equal(DiffChangeType.Moved, dep.ChangeType));
283	        Assert.Contains(removed.DependentChanges, dep => dep.FileName == "c.esm");
284	        Assert.Contains(removed.DependentChanges, dep => dep.FileName == "d.esm");
285	        Assert.Contains(removed.DependentChanges, dep => dep.FileName == "e.esm");
286	    }
287	
288	    // ==================================================================
289	    // Step 9h — Multiple consecutive replacements (tests cumulativeDeletions stays at 0)
290	    // ==================================================================
291	
292	    [Fact]
293	    public void ClassifyChanges_ConsecutiveReplacements_ReturnsTwoReplacedEntries()
294	    {
295	        // Reference: a(1) b(2) c(3) d(4)
296	        // Current:   a(1) x(2) y(3) d(4)   — b→x and c→y both replaced at same positions
297	        var reference = new[]
298	        {
299	            Mod("a.esm", 1),
300	            Mod("b.esm", 2),
301	            Mod("c.esm", 3),
302	            Mod("d.esm", 4),
303	        };
304	        var current = new[]
305	        {
306	            Mod("a.esm", 1),
307	            Mod("x.esm", 2),
308	            Mod("y.esm", 3),
309	            Mod("d.esm", 4),
310	        };
311	
312	        var lcs    = Lcs(reference, current);
313	        var result = DiffService.ClassifyChanges(reference, current, lcs);
314	
315	        Assert.Equal(2, result.Count);
316	        Assert.All(result, entry => Assert.Equal(DiffChangeType.Replaced, entry.ChangeType));
317	
318	        var replacedB = result.Single(e => e.FileName == "b.esm");
319	        Assert.Equal("x.esm", replacedB.ReplacementFileName);
320	
321	        var replacedC = result.Single(e => e.FileName == "c.esm");
322	        Assert.Equal("y.esm", replacedC.ReplacementFileName);
323	    }
324	
325	    // ==================================================================
326	    // Step 9i — Replacement with position shift (deletion before replacement)
327	    // ==================================================================
328	
329	    [Fact]
330	    public void ClassifyChanges_DeletionBeforeReplacement_AlignedPositionMatchesCorrectly()
331	    {
332	        // Reference: a(1) b(2) c(3) d(4)
333	        // Current:   a(1) c(2) x(3)
334	        //   — b is truly removed (shifts subsequent positions by 1)
335	        //   — d (aligned curPos = 4−1 = 3) is replaced by x
336	        //   — c shifts from refPos=3 to curPos=2 → dependent of b's removal
337	        var reference = new[]
338	        {
339	            Mod("a.esm", 1),
340	            Mod("b.esm", 2),
341	            Mod("c.esm", 3),
342	            Mod("d.esm", 4),
343	        };
344	        var current = new[]
345	        {
346	            Mod("a.esm", 1),
347	            Mod("c.esm", 2),
348	            Mod("x.esm", 3),
349	        };
350	
351	        var lcs    = Lcs(reference, current);
352	        var result = DiffService.ClassifyChanges(reference, current, lcs);
353	
354	        // b should be Removed (ref=2)
355	        var removedB = result.Single(e => e.FileName == "b.esm");
356	        Assert.Equal(DiffChangeType.Removed, removedB.ChangeType);
357	        Assert.Equal(2, removedB.ReferenceNumber);
358	
359	        // d should be Replaced by x (ref=4, aligned cur=4−1=3)
360	        var replacedD = result.Single(e => e.FileName == "d.esm");
361	        Assert.Equal(DiffChangeType.Replaced, replacedD.ChangeType);
362	        Assert.Equal("x.esm", replacedD.ReplacementFileName);
363	        Assert.Equal(4, replacedD.ReferenceNumber);
364	        Assert.Equal(3, replacedD.CurrentNumber);
365	    }
