371	    [Fact]
372	    public void ClassifyChanges_InsertionWithDependents_AttributesDependentsToInsertion()
373	    {
374	        // Reference: a(1) b(2) c(3)
375	        // Current:   a(1) new(2) b(3) c(4)   — new inserted at 2; b and c shift down
376	        var reference = new[]
377	        {
378	            Mod("a.esm", 1),
379	            Mod("b.esm", 2),
380	            Mod("c.esm", 3),
381	        };
382	        var current = new[]
383	        {
384	            Mod("a.esm",   1),
385	            Mod("new.esm", 2),
386	            Mod("b.esm",   3),
387	            Mod("c.esm",   4),
388	        };
389	
390	        var lcs    = Lcs(reference, current);
391	        var result = DiffService.ClassifyChanges(reference, current, lcs);
