393	        var inserted = Assert.Single(result);
394	        Assert.Equal(DiffChangeType.Inserted, inserted.ChangeType);
395	        Assert.Equal("new.esm", inserted.FileName);
396	        Assert.Equal(2, inserted.CurrentNumber);
397	
