399	        Assert.All(inserted.DependentChanges, dep => Assert.Equal(DiffChangeType.Moved, dep.ChangeType));
400	        Assert.Contains(inserted.DependentChanges, dep => dep.FileName == "b.esm");
401	        Assert.Contains(inserted.DependentChanges, dep => dep.FileName == "c.esm");
