 4	namespace LoadOrderKeeper.Models
 5	{
 6	    public enum DiffChangeType
 7	    {
 8	        Unchanged,
 9	        Added,
10	        Removed,
11	        Moved,
12	        Replaced,
13	        Inserted
14	    }
15	
16	    public sealed partial class DiffLineModel : ObservableObject
17	    {
18	        public DiffLineModel(string fileName, string text, DiffChangeType changeType, int? referenceNumber = null, int? currentNumber = null, string? replacementFileName = null)
19	        {
20	            FileName = fileName;
21	            Text = text;
22	            ChangeType = changeType;
23	            ReferenceNumber = referenceNumber;
24	            CurrentNumber = currentNumber;
25	            ReplacementFileName = replacementFileName;
26	            DependentChanges = new List<DiffLineModel>();
27	        }
28	
29	        public string FileName { get; }
30	
31	        public string Text { get; }
32	
33	        public DiffChangeType ChangeType { get; }
34	
35	        public int? ReferenceNumber { get; }
36	
37	        public int? CurrentNumber { get; }
38	
39	        public string? ReplacementFileName { get; }
40	
41	        public List<DiffLineModel> DependentChanges { get; }
42	
43	        public bool HasDependentChanges => DependentChanges.Count > 0;
44	
45	        public string DependentChangesSummary => $"+ {DependentChanges.Count} mod positions affected by this change";
46	
47	        [ObservableProperty]
48	        private bool _isDependentChangesExpanded;
49	
50	        public string Prefix => ChangeType switch
51	        {
52	            DiffChangeType.Added => "+",
53	            DiffChangeType.Removed => "-",
54	            DiffChangeType.Moved => "~",
55	            DiffChangeType.Replaced => ">",
56	            DiffChangeType.Inserted => "^",
57	            _ => string.Empty
